Tool response:
Tool: find_department_by_name_and_facility
Description: Retrieve the department ID given the department name and facility name.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Name of the department",
          "title": "Name"
        },
        "facility_name": {
          "type": "string",
          "description": "Name of the facility where the department is located",
          "title": "Facility Name"
        }
      },
      "required": [
        "name",
        "facility_name"
      ]
    }

Tool response:
Tool: create_asset
Description: Create a new asset record and attach a QR tag.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "manufacturer": {
          "type": "string",
          "title": "Manufacturer"
        },
        "model": {
          "type": "string",
          "title": "Model"
        },
        "serial_number": {
          "type": "string",
          "title": "Serial Number"
        },
        "department_id": {
          "type": "integer",
          "title": "Department Id"
        },
        "calibration_date": {
          "type": "string",
          "title": "Calibration Date"
        },
        "warranty_expiry": {
          "type": "string",
          "title": "Warranty Expiry"
        },
        "qr_tag_id": {
          "type": "string",
          "title": "Qr Tag Id"
        }
      },
      "required": [
        "name",
        "manufacturer",
        "model",
        "serial_number",
        "department_id",
        "calibration_date",
        "warranty_expiry",
        "qr_tag_id"
      ]
    }
